using System;using System.Linq;using System.IO;using Verse;using Verse.AI;using RimWorld;using PlayableRecreation;using PlayableRecreation.UI;using PRQA;
public static class Command{public static string Run(){TogetherMatch.Reset();var m=Find.CurrentMap;var b=((Thing[])Host.State["extensionBoards"])[0];var pair=new Pawn[2];for(int i=0;i<2;i++){var p=PawnGenerator.GeneratePawn(PawnKindDefOf.Colonist,Faction.OfPlayer);p.Name=new NameSingle("QA Punch "+i);GenSpawn.Spawn(p,b.Position+new IntVec3(-3,0,-2+i),m);p.needs.food.CurLevelPercentage=1;p.needs.rest.CurLevelPercentage=1;pair[i]=p;}Host.State["punchPair"]=pair;var game=b.TryGetComp<CompMiniGame>().Game;string log=Host.Root+"/punch-clean.txt";File.WriteAllText(log,"fresh pawns, refusal="+Together.Judge(pair[1],pair[0],b,game)+" seatCount="+Together.SeatCount(game)+"\n");GameEntry.Commit(game,b,pair[0],pair[1],1,false);int start=Find.TickManager.TicksGame,last=-1;Host.Watch=()=>{int t=Find.TickManager.TicksGame;if(t-last<60)return;last=t;File.AppendAllText(log,(t-start)+" window="+Find.WindowStack.Windows.Any(w=>w is Dialog_MiniGame)+" jobs="+pair[0].CurJobDef+","+pair[1].CurJobDef+" positions="+pair[0].Position+","+pair[1].Position+" canReserve="+pair[0].CanReserve(b,1,0)+","+pair[1].CanReserve(b,1,0)+"\n");if(t-start>450){Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;Host.Watch=null;}};Find.TickManager.CurTimeSpeed=TimeSpeed.Superfast;return "Independent reproduction with two fresh, eligible pawns.";}}
